```dart
group('vaster --version', () {
  test('prints "<tool> <version>\\n" to stdout and exits 0', () async {
    final out = StringBuffer();
    final exitCode = await runner.run(['--version'], stdoutSink: out);

    expect(exitCode, equals(0));
    expect(out.toString(), equals('vaster 0.2.0\n'));
  });

